#pragma once
#include "strata/kernels/original_mtp53_checkpoint_contract.hpp"
namespace strata::kernels::original_mtp53 {
struct ShiftedOriginalCheckpoint53 {
 std::vector<int32_t> target_inputs;int32_t lookahead=-1;
 OriginalCheckpoint53 current,pre_last;
 std::vector<uint8_t> last_target_hidden;
 std::string envelope_sha;
};
inline void validate_shifted53(const ShiftedOriginalCheckpoint53& c){
 validate_checkpoint53(c.current);validate_checkpoint53(c.pre_last);
 if(c.target_inputs.empty() || c.target_inputs.size()>4096 || c.current.cells!=c.target_inputs.size() || c.pre_last.cells+1!=c.current.cells || c.lookahead<0 || c.lookahead>=248320 || c.last_target_hidden.size()!=40960 || c.current.source_rid!=c.pre_last.source_rid || c.current.source_generation!=c.pre_last.source_generation || c.current.publisher_sha!=c.pre_last.publisher_sha || c.current.draft_contract_sha!=c.pre_last.draft_contract_sha || c.current.target_contract_sha!=c.pre_last.target_contract_sha || c.current.payload_sha!=checkpoint_digest53(c.current) || c.pre_last.payload_sha!=checkpoint_digest53(c.pre_last))throw std::runtime_error("shifted original complete envelope differs");
 for(int32_t t:c.target_inputs)if(t<0 || t>=248320)throw std::runtime_error("shifted actual target input invalid");
 std::vector<int32_t> known(c.target_inputs.begin()+1,c.target_inputs.end());if(c.pre_last.prefix!=known)throw std::runtime_error("shifted pre-last consumed NEXT prefix differs");known.push_back(c.lookahead);if(c.current.prefix!=known)throw std::runtime_error("shifted current consumed NEXT prefix differs");
 for(size_t i=0;i<c.last_target_hidden.size();i+=4){float f;std::memcpy(&f,c.last_target_hidden.data()+i,4);if(!std::isfinite(f))throw std::runtime_error("shifted authoritative MAIN hidden nonfinite");}
}
inline std::string shifted_digest53(const ShiftedOriginalCheckpoint53& c){validate_shifted53(c);strata::core::prefix_lifecycle::Sha256 h;const char schema[]="ORIGINAL-SHIFTED-NEXT-CP1";h.update(reinterpret_cast<const uint8_t*>(schema),sizeof(schema)-1);strata::core::prefix_lifecycle::digest_tokens(h,c.target_inputs);strata::core::prefix_lifecycle::number(h,uint32_t(c.lookahead));h.update(reinterpret_cast<const uint8_t*>(c.current.payload_sha.data()),64);h.update(reinterpret_cast<const uint8_t*>(c.pre_last.payload_sha.data()),64);h.update(c.last_target_hidden.data(),c.last_target_hidden.size());char out[65];h.finish(out);return out;}
inline std::vector<uint8_t> serialize_shifted53(const ShiftedOriginalCheckpoint53& c){validate_shifted53(c);if(c.envelope_sha!=shifted_digest53(c))throw std::runtime_error("shifted independent envelope digest differs");std::vector<uint8_t> out;auto n=[&](uint64_t v){for(int i=0;i<8;++i)out.push_back(uint8_t(v>>(8*i)));};auto bytes=[&](const std::vector<uint8_t>& b){n(b.size());out.insert(out.end(),b.begin(),b.end());};const std::string magic="ORIGINAL-SHIFTED-CP1";bytes(std::vector<uint8_t>(magic.begin(),magic.end()));n(c.target_inputs.size());for(int32_t t:c.target_inputs)for(int i=0;i<4;++i)out.push_back(uint8_t(uint32_t(t)>>(8*i)));n(uint32_t(c.lookahead));bytes(serialize_checkpoint53(c.current));bytes(serialize_checkpoint53(c.pre_last));bytes(c.last_target_hidden);out.insert(out.end(),c.envelope_sha.begin(),c.envelope_sha.end());return out;}
inline ShiftedOriginalCheckpoint53 deserialize_shifted53(const std::vector<uint8_t>& in,const std::string& pinned){if(in.size()>(41u<<20) || !checkpoint_sha53(pinned))throw std::runtime_error("shifted file/pin bound");size_t at=0;auto n=[&](){if(at>in.size() || in.size()-at<8)throw std::runtime_error("shifted number truncated");uint64_t v=0;for(int i=0;i<8;++i)v|=uint64_t(in[at++])<<(8*i);return v;};auto bytes=[&](size_t cap){auto count=n();if(count>cap || at>in.size() || count>in.size()-at)throw std::runtime_error("shifted bytes bound");std::vector<uint8_t> b(in.begin()+at,in.begin()+at+size_t(count));at+=size_t(count);return b;};auto magic=bytes(32);if(std::string(magic.begin(),magic.end())!="ORIGINAL-SHIFTED-CP1")throw std::runtime_error("shifted file schema differs");ShiftedOriginalCheckpoint53 c;auto count=n();if(count<1 || count>4096 || count*4>in.size()-at)throw std::runtime_error("shifted target prefix bound");for(size_t j=0;j<count;++j){uint32_t t=0;for(int i=0;i<4;++i)t|=uint32_t(in[at++])<<(8*i);c.target_inputs.push_back(int32_t(t));}auto look=n();if(look>=248320)throw std::runtime_error("shifted lookahead invalid");c.lookahead=int32_t(look);auto current=bytes(20u<<20),pre=bytes(20u<<20);if(current.size()<64 || pre.size()<64)throw std::runtime_error("shifted inner hashes missing");c.current=deserialize_checkpoint53(current,std::string(current.end()-64,current.end()));c.pre_last=deserialize_checkpoint53(pre,std::string(pre.end()-64,pre.end()));c.last_target_hidden=bytes(40960);if(in.size()-at!=64)throw std::runtime_error("shifted trailing data/hash");c.envelope_sha=std::string(in.begin()+at,in.end());validate_shifted53(c);if(c.envelope_sha!=pinned || c.envelope_sha!=shifted_digest53(c))throw std::runtime_error("shifted full source/payload pin differs");return c;}

}
